css:
.header {
    text-align: center;
    font-weight: bold;
    font-size: 18px;
}

.sub-header {
    text-align: center;
    font-size: 14px;
    margin-bottom: 15px;
}

/* Employee Info Table */
.info-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 10px;
    margin-bottom: 15px;
}

.info-table td {
    border: 1px solid black;
    padding: 6px;
    font-size: 13px;
}

.table-heading {
    text-align: center;
    background-color: #f2f2f2;
    font-weight: bold;
}

/* Section Title */
.section-title {
    margin-top: 15px;
    margin-bottom: 5px;
    font-size: 14px;
    font-weight: bold;
}

/* Loan Table */
.loan-table {
    width: 100%;
    border-collapse: collapse;
}

.loan-table th,
.loan-table td {
    border: 1px solid black;
    padding: 5px;
    font-size: 13px;
}

.loan-table th {
    text-align: center;
    background-color: #f2f2f2;
}

/* Salary Details Table */
.emoluments-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 13px;
    margin-top: 10px;
}

.emoluments-table th,
.emoluments-table td {
    border: 1px solid black;
    padding: 5px;
}

.emoluments-table th {
    text-align: center;
    background-color: white !important;

}

/* Align numbers right */
.emoluments-table td:nth-child(2),
.emoluments-table td:nth-child(3),
.emoluments-table td:nth-child(5),
.emoluments-table td:nth-child(6) {
    text-align: right;
}

/* Main earnings table (if used) */
.main-table {
    width: 100%;
    border-collapse: collapse;
}

.main-table th,
.main-table td {
    border: 1px solid black;
    padding: 6px;
}

/* No border */
.no-border td {
    border: none !important;
}
